(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.016+t*0.38)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.012-t*0.15)*8 + Math.cos(sy*0.01+t*0.2)*6;
  const w2y = Math.cos(sy*0.014+t*0.18)*8 + Math.sin(sx*0.011-t*0.25)*6;
  const dx = sx + w2x, dy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.13, 1.8, 1.15],
    [200+Math.sin(t*0.25+6)*110, 60+Math.cos(t*0.45+3)*80, 0.055, 2.8, 1.0]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2+=Math.sin(d*f*1.4-t*sp*1.2+0.8)*w;
    iS2+=Math.sin(d*f*0.5+t*sp*0.4+3.0)*w;
  }
  const nw=9;
  const act=(aS+0.4*aS2)/nw, inh=(iS+0.35*iS2)/nw;
  const n1=Math.sin(dx*0.04+dy*0.025+t*0.8);
  const n2=Math.sin(dx*0.03-dy*0.04+t*1.1);
  const n3=Math.sin((dx+dy)*0.12+t*2.5)*0.2;
  const n4=Math.sin((dx-dy)*0.1-t*2)*0.2;
  const n5=Math.sin(dx*0.07-dy*0.05+t*1.6)*0.15;
  const bg=(n1+n2+n3+n4+n5)/2;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2);
  const ang=Math.atan2(dy-cy,dx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08+ang*5-t*2.1)*Math.sin(dist*0.03-ang*2+t*0.8)*0.25;
  const spiral=sp1+sp2;
  const ring=Math.sin(dist*0.12-t*3)*Math.exp(-dist*0.005)*0.5;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((aS2/nw-iS2*0.5/nw+ring)*1.8);
  const cell=Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(dx*0.4+t*3)*Math.sin(dy*0.35-t*2.5)*0.08;
  const blend=r1*0.5+r2*0.2+cell*0.2+micro;
  const v=blend*0.5+0.5;
  const shift=Math.sin(t*0.15)*0.3+0.5;
  const pal=[
    [5,12,55],[12,45,95],[18,90,120],[30,140,130],
    [80,175,140],[180,195,100],[220,170,65],
    [210,115,55],[175,60,60],[120,30,55],[60,15,45],[5,12,55]
  ];
  const idx=v*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2);
  const f=idx-i;
  const c0=pal[i],c1=pal[i+1];
  const lum=0.75+Math.sin(r1*Math.PI)*0.15+Math.abs(r2)*0.1;
  const edge=Math.abs(r1)>0.65?1.2:Math.abs(r2)>0.5?1.1:1.0;
  const glow=Math.max(0,1-dist/280)*0.15*Math.abs(r1);
  return[
    Math.min(255,((c0[0]+(c1[0]-c0[0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((c0[1]+(c1[1]-c0[1])*f)*lum*edge+glow*80)|0),
    Math.min(255,((c0[2]+(c1[2]-c0[2])*f)*lum*edge+glow*120)|0)
  ];
}
